def remove_Occ(s, ch):
    """Write a python function to remove first and last occurrence of a given character from the string."""
    if not s or not ch:
        return s
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first + len(ch):]
    return s[:first] + s[first + len(ch):last] + s[last + len(ch):]
